INSERT INTO `ai_knowledge` VALUES (2,'测试标题','测试描述',45,'embo-01',3,0.5,0,'1','2025-03-02 18:23:35','1','2025-05-03 16:50:54',_binary '',1),(3,'测试 QdrantVectorStore','测试 QdrantVectorStore',45,'minimax-text-01',2,0.5,0,'1','2025-03-05 12:57:33','1','2025-03-11 20:13:01',_binary '\0',1),(4,'测试 RedisVectorStore',NULL,30,'nomic-embed-text',10,0.1,0,'1','2025-03-08 17:51:34','1','2025-03-08 17:51:34',_binary '\0',1),(5,'测试 MilvusVectorStore',NULL,30,'nomic-embed-text',10,0.1,0,'1','2025-03-09 09:15:12','1','2025-03-09 09:15:12',_binary '\0',1),(6,'测试 SimpleVectorStore','临时的测试',30,'nomic-embed-text',10,0.01,0,'1','2025-05-03 16:57:39','1','2025-05-03 16:57:39',_binary '\0',1);
