DROP TABLE IF EXISTS `base_business_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `base_business_type` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `business_type_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'business type code',
  `business_type_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'business type name',
  `business_category` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'business category',
  `operation_flow_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'operation flow type',
  `receive_required` bit(1) NOT NULL DEFAULT b'0' COMMENT 'receive required',
  `inbound_required` bit(1) NOT NULL DEFAULT b'0' COMMENT 'inbound required',
  `putaway_required` bit(1) NOT NULL DEFAULT b'0' COMMENT 'putaway required',
  `storage_required` bit(1) NOT NULL DEFAULT b'0' COMMENT 'storage required',
  `picking_required` bit(1) NOT NULL DEFAULT b'0' COMMENT 'picking required',
  `outbound_required` bit(1) NOT NULL DEFAULT b'0' COMMENT 'outbound required',
  `delivery_required` bit(1) NOT NULL DEFAULT b'0' COMMENT 'delivery required',
  `appointment_required` bit(1) NOT NULL DEFAULT b'0' COMMENT 'appointment required',
  `vas_supported` bit(1) NOT NULL DEFAULT b'0' COMMENT 'vas supported',
  `billing_mode` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'billing mode',
  `sorting_strategy` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'sorting strategy',
  `sorting_field` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'sorting field',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT 'sort order',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0 enable 1 disable',
  `remark` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'remark',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT 'creator',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'create time',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT 'updater',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'update time',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT 'deleted',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT 'tenant id',
  PRIMARY KEY (`id`),
