  `business_type_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类型名称',
  `dock_location` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '月台位置',
