  `occupied_object_id` bigint DEFAULT NULL COMMENT '占用对象 ID',
  `occupied_object_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '占用对象编号',
  `occupied_since` datetime DEFAULT NULL COMMENT '占用开始时间',
