DROP TABLE IF EXISTS `yard_zone`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `yard_zone` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `warehouse_id` bigint NOT NULL COMMENT '仓库 ID',
  `zone_code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分区编码',
  `zone_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分区名称',
  `zone_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CONTAINER' COMMENT '分区类型',
  `sort_order` int DEFAULT NULL COMMENT '排序',
  `remark` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_yard_zone_code` (`tenant_id`,`zone_code`,`deleted`),
  KEY `idx_yard_zone_warehouse` (`warehouse_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='堆场分区';
